import java.math.BigDecimal;
import java.math.RoundingMode;

public class PriceCalculator {

    private static final BigDecimal DISCOUNT_THRESHOLD = new BigDecimal("100");
    private static final BigDecimal DISCOUNT_RATE = new BigDecimal("0.9");
    private static final int SCALE = 2;

    public static BigDecimal payable(BigDecimal amount, boolean member) {
        if (amount == null || amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("amount must not be null or negative");
        }

        BigDecimal result;
        if (member && amount.compareTo(DISCOUNT_THRESHOLD) >= 0) {
            result = amount.multiply(DISCOUNT_RATE);
        } else {
            result = amount;
        }

        return result.setScale(SCALE, RoundingMode.HALF_UP);
    }
}
